import{_ as t,o as a,c as i,ah as r}from"./chunks/framework.CRsDMGp2.js";const f=JSON.parse(`{"title":"Guide — Apporteur d'affaires","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/apporteur-affaires.md","filePath":"src/guide/apporteur-affaires.md"}`),o={name:"guide/apporteur-affaires.md"};function s(n,e,u,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="guide-—-apporteur-d-affaires" tabindex="-1">Guide — Apporteur d&#39;affaires <a class="header-anchor" href="#guide-—-apporteur-d-affaires" aria-label="Permalink to &quot;Guide — Apporteur d&#39;affaires&quot;">​</a></h1><p>Suivre votre portefeuille de clients et vos commissions.</p><h2 id="bienvenue-sur-naia" tabindex="-1">Bienvenue sur Naia <a class="header-anchor" href="#bienvenue-sur-naia" aria-label="Permalink to &quot;Bienvenue sur Naia&quot;">​</a></h2><p>Votre espace Naia vous donne une vue consolidée sur les projets des clients que vous avez apportés à edPage group.</p><h2 id="votre-portefeuille" tabindex="-1">Votre portefeuille <a class="header-anchor" href="#votre-portefeuille" aria-label="Permalink to &quot;Votre portefeuille&quot;">​</a></h2><p>Votre tableau de bord regroupe :</p><ul><li>le nombre total de projets de votre portefeuille, par statut ;</li><li>l&#39;avancement de chaque projet (jalons atteints, tâches) ;</li><li>vos projets récents, avec accès direct à leur fiche.</li></ul><p>Depuis la fiche d&#39;un projet, vous retrouvez les mêmes onglets Suivi/Collaboration/Finance que les autres intervenants (dans la limite de ce qui vous concerne) : consultez les livrables et rapports partagés, et déposez vos propres documents (pièces client, informations complémentaires) depuis l&#39;onglet Documents.</p><h2 id="facturation-et-suivi-financier" tabindex="-1">Facturation et suivi financier <a class="header-anchor" href="#facturation-et-suivi-financier" aria-label="Permalink to &quot;Facturation et suivi financier&quot;">​</a></h2><ul><li>Suivez l&#39;échéancier de paiement et le statut de facturation des projets de votre portefeuille (échéances dues, réglées, à venir) depuis l&#39;onglet <strong>Facturation</strong> de chaque projet.</li><li>Vous êtes notifié en cas de suspension pour impayé sur l&#39;un de vos projets.</li><li>Votre tableau de bord affiche le cumul de vos <strong>commissions dues et versées</strong>, calculées automatiquement sur les encaissements effectivement reçus des clients de vos projets (pas seulement sur le montant facturé) — votre taux de commission est fixé par l&#39;administrateur et indiqué dans votre contrat de mandat.</li></ul><h2 id="inviter-un-client" tabindex="-1">Inviter un client <a class="header-anchor" href="#inviter-un-client" aria-label="Permalink to &quot;Inviter un client&quot;">​</a></h2><p>Depuis votre espace, vous pouvez inviter un client sur la plateforme (menu <strong>Inviter</strong>) et suivre l&#39;activation de son accès. C&#39;est le seul type de compte que vous pouvez inviter directement.</p><h2 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h2><p>Échangez avec le chef de projet interne sur les projets de votre portefeuille via la messagerie intégrée, et recevez des notifications sur les étapes clés et les points de vigilance (retard, impayé).</p>',14)])])}const v=t(o,[["render",s]]);export{f as __pageData,v as default};
